import sys
import xml.etree.ElementTree as ET
import csv
import io

def parse_xml_config(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        if root.tag != 'report':
            raise ValueError("Root element must be <report>")
        title = root.find('title')
        if not title:
            raise ValueError("Missing <title> element")
        columns = root.find('columns')
        if not columns:
            raise ValueError("Missing <columns> element")
        config = {
            'title': title.text.strip() if title.text else '',
            'columns': []
        }
        for col_elem in columns.findall('column'):
            if not col_elem.get('source') or not col_elem.get('label'):
                raise ValueError("Column must have 'source' and 'label' attributes")
            config['columns'].append({
                'source': col_elem.get('source'),
                'label': col_elem.get('label')
            })
        return config
    except (IOError, ET.ParseError) as e:
        print(f"Error reading XML file: {e}", file=sys.stderr)
        sys.exit(1)

def parse_csv_data(csv_data):
    reader = csv.reader(io.StringIO(csv_data), quotechar='"', quoting=csv.QUOTE_MINIMAL)
    headers = next(reader)
    rows = []
    for row in reader:
        rows.append(row)
    return headers, rows

def generate_html(config, headers, rows):
    html = [
        '<!DOCTYPE html>',
        '<html>',
        '<head>',
        '<meta charset="utf-8">',
        f'<title>{config["title"]}</title>',
        '</head>',
        '<body>',
        f'<h1>{config["title"]}</h1>',
        '<table>',
        '<tr>'
    ]

    # Write column headers
    for col in config['columns']:
        html.append(f'<th>{col["label"]}</th>')
    html.append('</tr>')

    # Write data rows
    for row in rows:
        html.append('<tr>')
        for col in config['columns']:
            source = col['source']
            if source in headers:
                html.append(f'<td>{row[headers.index(source)]}</td>')
            else:
                html.append('<td></td>')
        html.append('</tr>')

    html.append('</table>')
    html.append('</body>')
    html.append('</html>')

    return '\n'.join(html)

def main():
    if len(sys.argv) != 2:
        print("Usage: python render_report.py <xml_config_file>", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    config = parse_xml_config(xml_path)

    csv_data = sys.stdin.read()
    headers, rows = parse_csv_data(csv_data)

    html = generate_html(config, headers, rows)
    print(html)

if __name__ == '__main__':
    main()

