import sys
import xml.etree.ElementTree as ET
from io import StringIO

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    title = root.find('title').text
    columns = []
    for col in root.find('columns'):
        name = col.get('name')
        label = col.get('label')
        columns.append((name, label))
    return title, columns

def parse_csv(csv_data):
    lines = csv_data.strip().split('\n')
    headers = [h.strip() for h in lines[0].split(',')]
    data = []
    for line in lines[1:]:
        fields = [f.strip() for f in line.split(',')]
        row = []
        for header in headers:
            row.append(fields[headers.index(header)] if header in fields else '')
        data.append(row)
    return headers, data

def generate_html(title, columns, headers, data):
    html = f"""<!DOCTYPE html>
<html>
<head>
    <title>{title}</title>
    <style>
        table {{
            border-collapse: collapse;
            width: 100%;
        }}
        th, td {{
            border: 1px solid #ddd;
            padding: 8px;
            text-align: left;
        }}
        th {{
            background-color: #f2f2f2;
        }}
    </style>
</head>
<body>
    <h1>{title}</h1>
    <table>
        <tr>
            {', '.join(f'<th>{label}</th>' for name, label in columns)}
        </tr>
        {', '.join(f'<tr>{', '.join(f'<td>{data[headers.index(name)] if name in headers else ""}</td>' for name, _ in columns)}</tr>' for data in data)}
    </table>
</body>
</html>"""
    return html

def main():
    if len(sys.argv) != 2:
        print("Usage: python render_report.py <xml_config_file>", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    try:
        title, columns = parse_xml(xml_path)
    except ET.ParseError as e:
        print(f"Error parsing XML: {e}", file=sys.stderr)
        sys.exit(1)

    csv_data = sys.stdin.read()
    headers, data = parse_csv(csv_data)

    html = generate_html(title, columns, headers, data)
    print(html)

if __name__ == "__main__":
    main()
